INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(3601, 'Numbers 6:17', 'Numbers', 6, 17, '&nbsp;هغه به ګډ د سلامتۍ نذرانې په توګه مالِک خُدائ ته قربانى کړى او د هغه پتيرې روټۍ سره به يې پېش کړى کومه چې په ټوکرۍ کښې ده، هغه به د غلې او د څښلو نذرانې هم حاضرې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3602, 'Numbers 6:18', 'Numbers', 6, 18, '&nbsp;هغه د نذير په حيثيت کس به د مقدسې خېمې په دروازه کښې خپل وېښتۀ کل کړى او په هغه اور کښې به يې واچوى چې په کوم د سلامتۍ نذرانه سوزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3603, 'Numbers 6:19', 'Numbers', 6, 19, '&nbsp;بيا کله چې د ګډ د اوږې غوښه ويشولے شى، اِمام به دا راواخلى او په ټوکرۍ کښې چې کومې روټۍ دى د يوې ډبلې او د يوې نرۍ روټۍ سره به يې د هغه د نذير په حيثيت کس په لاسونو کښې کېږدى چا چې قسم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3604, 'Numbers 6:20', 'Numbers', 6, 20, '&nbsp;بيا به اِمام دا د يوې خاص تُحفې په توګه مالِک خُدائ ته پېش کړى، دا د اِمام دپاره يوه مقدسه نذرانه ده، د دې نه علاوه د ګډ سينه او پتُون د قانون په مطابق د اِمام دى، نو بيا، هغه کس چې د نذير په حيثيت يې قسم خوړلے وو، مے څښلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3605, 'Numbers 6:21', 'Numbers', 6, 21, '&nbsp;دا اصُول د هغه کس دپاره دى کوم چې د نذير په حيثيت مالِک خُدائ ته قسم وکړى. د دې نه علاوه نورې نذرانې هم پېش کولے شى کۀ د هغۀ وس وى. خو هغوئ چې کومه وعده کړې وى نو هغه به خامخا پوره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3606, 'Numbers 6:22', 'Numbers', 6, 22, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3607, 'Numbers 6:23', 'Numbers', 6, 23, '&nbsp;چې هارون او د هغۀ زامن دې د بنى اِسرائيلو د برکت غوښتلو دپاره داسې وائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3608, 'Numbers 6:24', 'Numbers', 6, 24, '&nbsp;”مالِک خُدائ دې تاسو له برکت درکړى او ستاسو خيال دې وساتى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3609, 'Numbers 6:25', 'Numbers', 6, 25, '&nbsp;مالِک خُدائ دې د خپل مخ نُور په تاسو وځلوى او په تاسو دې رحم وکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3610, 'Numbers 6:26', 'Numbers', 6, 26, '&nbsp;مالِک خُدائ دې ستاسو مل وى او تاسو له دې سلامتى درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3611, 'Numbers 6:27', 'Numbers', 6, 27, '&nbsp;او مالِک خُدائ وفرمائيل، ”چې هغوئ په بنى اِسرائيلو باندې د برکت دپاره زما نوم اخلى، نو زۀ به هغوئ له برکت ورکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3612, 'Numbers 7:1', 'Numbers', 7, 1, '&nbsp;په هغه ورځ چې کله موسىٰ د مالِک خُدائ د حضور مقدسه خېمه ودرول پوره کړل، هغۀ مقدسه خېمه او د دې ټول سامان، قربان‌ګاه او د هغې ټول سامان په تېلو غوړ کړل او وقف يې کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3613, 'Numbers 7:2', 'Numbers', 7, 2, '&nbsp;بيا د بنى اِسرائيلو د قبيلو مشران، کوم چې د مردم‌شمارۍ مشران وُو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3614, 'Numbers 7:3', 'Numbers', 7, 3, '&nbsp;هغوئ خپلې نذرانې مالِک خُدائ ته راوړلې، شپږ لوئې ګاډۍ او دولس غوائى، د دوو مشرانو دپاره يوه ګاډۍ او د هر مشر دپاره يو غوَيے. کله چې هغوئ دا حاضر کړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3615, 'Numbers 7:4', 'Numbers', 7, 4, '&nbsp;نو مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3616, 'Numbers 7:5', 'Numbers', 7, 5, '&nbsp;”دا تُحفې قبولې کړه چې د مقدسې خېمې په خِدمت کښې استعمال شى، دا ليويانو ته د هغه خِدمت دپاره ورکړه کوم چې هغوئ کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3617, 'Numbers 7:6', 'Numbers', 7, 6, '&nbsp;نو موسىٰ ګاډۍ او غوَيان ليويانو له ورکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3618, 'Numbers 7:7', 'Numbers', 7, 7, '&nbsp;هغۀ دوه ګاډۍ او څلور غوائى جيرسونيانو له ورکړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3619, 'Numbers 7:8', 'Numbers', 7, 8, '&nbsp;او څلور ګاډۍ او اتۀ غوَيان يې مراريانو له ورکړل. دا ټول خِدمت د هارون زوئ اِتمر د رهنمايۍ لاندې وشو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3620, 'Numbers 7:9', 'Numbers', 7, 9, '&nbsp;خو قُهاتيانو له يې ګاډۍ يا غوَيان ورنۀ کړل، ځکه چې هغوئ د کومو مقدسو څيزونو ساتنه کوله هغه هغوئ په اوږو باندې وړلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3621, 'Numbers 7:10', 'Numbers', 7, 10, '&nbsp;مشرانو د قربان‌ګاه وقف کولو دپاره هم نذرانې راوړې. کله چې هغوئ خپلې نذرانې په قربان‌ګاه باندې پېش کولو ته تيار شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3622, 'Numbers 7:11', 'Numbers', 7, 11, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”مشرانو ته ووايه چې دولس ورځې به هره ورځ يو يو مشر د قربان‌ګاه د وقف کولو دپاره خپلې نذرانې پېش کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3623, 'Numbers 7:89', 'Numbers', 7, 89, '&nbsp;کله چې موسىٰ مقدسې خېمې ته دننه لاړو چې د مالِک خُدائ سره خبرې وکړى، هغۀ د مالِک خُدائ خبرې واورېدلې چې د لوظ د صندوق د سر دپاسه او د دوه وزرو والا مخلوق د مينځ نه يې د هغۀ سره کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3624, 'Numbers 8:1', 'Numbers', 8, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3625, 'Numbers 8:2', 'Numbers', 8, 2, '&nbsp;”هارون ته ووايه چې کله هغه اووۀ ډيوې په ډيوټ باندې کېږدى، نو هغه به يې داسې کېږدى چې د ډيوټ مخې ته رڼا ورکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3626, 'Numbers 8:3', 'Numbers', 8, 3, '&nbsp;هارون هم هغه شان وکړل او ډيوې يې داسې کېښودې چې د ډيوټ مخې ته رڼا وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3627, 'Numbers 8:4', 'Numbers', 8, 4, '&nbsp;د سر نه تر بېخه پورې ډيوټ د ټکولے شوو سرو زرو نه جوړ وو، هم د هغې نقشې په مطابق چې مالِک خُدائ موسىٰ ته ښودلې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3628, 'Numbers 8:5', 'Numbers', 8, 5, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3629, 'Numbers 8:6', 'Numbers', 8, 6, '&nbsp;”ليويان د نورو بنى اِسرائيلو نه جدا کړه او هغوئ پاک کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3630, 'Numbers 8:7', 'Numbers', 8, 7, '&nbsp;طريقه دا ده، په هغوئ باندې د پاکوالى اوبۀ وشينده او هغوئ ته ووايه چې ټول بدن کل کړى او خپلې جامې ووينځى. نو هغوئ به پاک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3631, 'Numbers 8:8', 'Numbers', 8, 8, '&nbsp;بيا يو سخے او د غلې نذرانې دپاره اوړۀ چې د زيتُونو تېل ورسره ګډ وى دا به هغوئ واخلى، او د ګناه نذرانې دپاره به تۀ يو بل غوَيے بوځې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3632, 'Numbers 8:9', 'Numbers', 8, 9, '&nbsp;بيا د بنى اِسرائيلو ټول قوم راغونډ کړه او ليويان زما د حضور خېمې په مخکښې ودروه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3633, 'Numbers 8:10', 'Numbers', 8, 10, '&nbsp;اِسرائيليان دې خپل لاسونه د ليويانو په سرونو کېږدى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3634, 'Numbers 8:11', 'Numbers', 8, 11, '&nbsp;او بيا به هارون ليويان د بنى اِسرائيلو نه د خاص تُحفې په توګه ما ته وقف کړى، چې هغوئ زما خِدمت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3635, 'Numbers 8:12', 'Numbers', 8, 12, '&nbsp;ليويان به بيا خپل لاسونه د دوو غوَيانو په سرونو کېږدى، يو به د ګناه نذرانې په توګه او بل د سوزېدونکې نذرانې په توګه مالِک خُدائ ته پېش کيږى، د دې دپاره چې د ليويانو کفاره ادا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3636, 'Numbers 8:13', 'Numbers', 8, 13, '&nbsp;ليويان ما ته د خاص تُحفې په توګه وقف کړه او هارون او د هغۀ زامن د هغوئ مشران جوړ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3637, 'Numbers 8:14', 'Numbers', 8, 14, '&nbsp;نو ليويان د نورو بنى اِسرائيلو نه جدا کړه چې هغوئ زما شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3638, 'Numbers 8:15', 'Numbers', 8, 15, '&nbsp;کله چې تۀ ليويان پاک او وقف کړې، نو هغوئ د خِدمت دپاره مقدسې خېمې ته دننه تلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3639, 'Numbers 8:16', 'Numbers', 8, 16, '&nbsp;د بنى اِسرائيلو د ټولو مشرانو زامنو په ځائ ليويان زما دى او هغوئ صِرف زما دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3640, 'Numbers 8:17', 'Numbers', 8, 17, '&nbsp;کله چې ما د مِصر په مُلک کښې ټول مشران زامن ووژل، ما د بنى اِسرائيلو د هر خاندان مشر زوئ او هر يو وړومبے پېدا شوے ځناور خپل ځان ته وقف کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3641, 'Numbers 8:18', 'Numbers', 8, 18, '&nbsp;اوس زۀ د بنى اِسرائيلو د ټولو وړومبو پېدا شوو زامنو په ځائ ليويان اخلم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3642, 'Numbers 8:19', 'Numbers', 8, 19, '&nbsp;او ليويان د بنى اِسرائيلو نه د خاص تُحفې په توګه د هارون او د هغۀ زامنو په حواله کوم چې په مقدسه خېمه کښې د بنى اِسرائيلو دپاره خِدمت وکړى او هغوئ به د بنى اِسرائيلو دپاره کفاره ادا کوى چې کله هغوئ مقدس ځائ ته ډېر نزدې راشى نو چې وبا يې هلاک نۀ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3643, 'Numbers 8:20', 'Numbers', 8, 20, '&nbsp;نو موسىٰ، هارون او ټولو بنى اِسرائيلو ليويان وقف کړل، هم هغه شان چې څنګه مالِک خُدائ موسىٰ ته حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3644, 'Numbers 8:21', 'Numbers', 8, 21, '&nbsp;ليويانو خپل ځانونه پاک کړل او جامې يې ووينځلې او هارون هغوئ مالِک خُدائ ته د خاص تُحفې په توګه پېش کړل. هارون د هغوئ دپاره د پاکوالى کفاره ادا کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3645, 'Numbers 8:22', 'Numbers', 8, 22, '&nbsp;خلقو هم هغه شان وکړل چې څنګه مالِک خُدائ د ليويانو په حقله موسىٰ ته حُکم کړے وو. نو ليويان په مقدسه خېمه کښې د خِدمت کولو دپاره د هارون او د هغۀ زامنو د مشرۍ لاندې لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3646, 'Numbers 8:23', 'Numbers', 8, 23, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3647, 'Numbers 8:24', 'Numbers', 8, 24, '&nbsp;”د پينځويشتو کالو عُمر نه واخله هر يو ليوے به زما د حضور په خېمه کښې خپله د خِدمت ذمه وارى ادا کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3648, 'Numbers 8:25', 'Numbers', 8, 25, '&nbsp;او چې عُمر يې پنځوس کاله شى نو هغه به نور خِدمت نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3649, 'Numbers 8:26', 'Numbers', 8, 26, '&nbsp;د هغې نه پس، هغه د خپل هغه ليوى سره مدد کولے شى کوم چې په خېمه کښې خپله ذمه وارى ادا کوى، خو په خپله به هيڅ خِدمت نۀ کوى. نو داسې به تاسو ليويانو ته ذمه وارۍ حواله کوئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3650, 'Numbers 9:1', 'Numbers', 9, 1, '&nbsp;د بنى اِسرائيلو د مِصر مُلک نه د وتلو نه پس، د دوېم کال په اولنۍ مياشت مالِک خُدائ د سينا په بيابان کښې د موسىٰ سره خبرې وکړې. مالِک خُدائ ورته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3651, 'Numbers 9:4', 'Numbers', 9, 4, '&nbsp;نو موسىٰ بنى اِسرائيلو ته وفرمائيل چې هغوئ د فسحې اختر وکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3652, 'Numbers 9:5', 'Numbers', 9, 5, '&nbsp;او د اولنۍ مياشتې د څوارلسمې ورځې په ماښام بنى اِسرائيلو د سينا په بيابان کښې هغه هر څۀ وکړل چې څنګه مالِک خُدائ موسىٰ له حُکم ورکړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3653, 'Numbers 9:6', 'Numbers', 9, 6, '&nbsp;خو څۀ خلق ناپاک وُو ځکه چې هغوئ د مړى سره لګېدلى وُو او هغوئ په هغه ورځ د فسحې اختر نۀ شو کولے. هغوئ موسىٰ او هارون له لاړل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3654, 'Numbers 9:7', 'Numbers', 9, 7, '&nbsp;او ورته يې ووئيل، ”مونږ ناپاک يُو ځکه چې مونږ د مړى سره لګېدلى يُو، خو مونږ د نورو بنى اِسرائيلو سره ولې نۀ شُو شريکېدلے چې مالِک خُدائ ته نذرانه پېش کړُو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3655, 'Numbers 9:8', 'Numbers', 9, 8, '&nbsp;موسىٰ ورته وفرمائيل، ”تر هغې پورې صبر وکړئ چې ما ته د مالِک خُدائ نه ستاسو په حقله حُکم مِلاو شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3656, 'Numbers 9:9', 'Numbers', 9, 9, '&nbsp;نو مالِک خُدائ موسىٰ ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3657, 'Numbers 9:10', 'Numbers', 9, 10, '&nbsp;”بنى اِسرائيلو ته ووايه، کله چې تاسو يا ستاسو اولاد د مړى سره لګېدلو په وجه ناپاک يئ يا په لرې سفر کښې يئ، خو بيا هم د فسحې اختر کول غواړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3658, 'Numbers 9:11', 'Numbers', 9, 11, '&nbsp;نو تاسو ته اجازت دے چې دا يوه مياشت وروستو وکړئ، يعنې د دوېمې مياشتې د څوارلسمې ورځې په ماښام. دا اختر د پتيرې روټۍ او ترخو بوټو سره وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3659, 'Numbers 9:12', 'Numbers', 9, 12, '&nbsp;د هغه خوراک نه هيڅ هم د بل سحر پورې مۀ پرېږدئ او چې د هغه قربانۍ د ځناورو هډُوکى مات نۀ کړئ. د فسحې اختر د ټولو اصُولو په مطابق وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3660, 'Numbers 9:13', 'Numbers', 9, 13, '&nbsp;خو چې څوک پاک وى او لرې سفر کښې نۀ وى او هغه د فسحې اختر ونۀ کړى، نو هغه به نور زما د خلقو نه نۀ شى ګڼلے، ځکه چې هغۀ ما ته په مقرر وخت باندې نذرانه پېش نۀ کړه. هغۀ ته به خامخا د خپلې ګناه سزا مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3661, 'Numbers 9:14', 'Numbers', 9, 14, '&nbsp;ستاسو سره چې کوم مسافر اوسيږى کۀ هغوئ د فسحې اختر کول غواړى، نو هغوئ به دا د ټول قانون او اصُولو په مطابق کوى. هر څوک چې د بل مُلک وى يا په دې مُلک کښې پېدا شوے وى نو د دواړو دپاره يو شان قانون دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3662, 'Numbers 9:17', 'Numbers', 9, 17, '&nbsp;چې کله به هم وريځ د خېمې نه اوچته شوه، نو اِسرائيليان به روان شول او بيا به يې په هغه ځائ کښې خېمې ودرولې چرته به چې وريځ راکوزه شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3663, 'Numbers 9:18', 'Numbers', 9, 18, '&nbsp;بنى اِسرائيلو به د مالِک خُدائ په حُکم خېمې وړلې او د هغۀ په حُکم به يې ودرولې. تر کومې پورې به چې وريځ په مقدسه خېمه باندې ولاړه وه، نو هغوئ به په خپلو خېمو کښې ايسار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3664, 'Numbers 9:19', 'Numbers', 9, 19, '&nbsp;کله به چې وريځ په مقدسه خېمه باندې د ډېر وخت دپاره ولاړه وه، نو هغوئ د مالِک خُدائ حُکم منلو او د هغه ځائ نه به نۀ تلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3665, 'Numbers 9:20', 'Numbers', 9, 20, '&nbsp;کله کله به وريځ صِرف يو څو ورځې د خېمې دپاسه ايساره وه، نو په هر حالت کښې، هغوئ د مالِک خُدائ د حُکم په مطابق په خپلو خېمو کښې ايسارېدل يا به يې سفر کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3666, 'Numbers 9:21', 'Numbers', 9, 21, '&nbsp;کله به وريځ صِرف د ماښام نه واخله تر سحره پورې ايساره وه، چې څنګه به وريځ اوچته شوه نو هغوئ به سفر شروع کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3667, 'Numbers 9:22', 'Numbers', 9, 22, '&nbsp;کۀ وريځ به دوه ورځې، مياشت، کال، يا زياته د مقدسې خېمې دپاسه ولاړه وه، نو هغوئ به سفر نۀ کولو، خو چې کله به وريځ اوچته شوه، نو هغوئ به سفر کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3668, 'Numbers 9:23', 'Numbers', 9, 23, '&nbsp;کوم حُکمونه چې مالِک خُدائ د موسىٰ په ذريعه ورکړى وُو هغوئ د هغې په مطابق خېمې ودرولې او وړلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3669, 'Numbers 10:1', 'Numbers', 10, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3670, 'Numbers 10:2', 'Numbers', 10, 2, '&nbsp;”د ټکېدلے شوو سپينو زرو نه دوه بيګلې جوړې کړه چې د خلقو په يو ځائ راغونډولو او د خېمو د وړلو د خبر دپاره استعماليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3671, 'Numbers 10:3', 'Numbers', 10, 3, '&nbsp;کله چې دواړه بيګلې وغږيږى، نو ټول قوم به زما د حضور د مقدسې خېمې په دروازه کښې ستا نه ګېرچاپېره راغونډ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3672, 'Numbers 10:4', 'Numbers', 10, 4, '&nbsp;خو چې کله صِرف يو بيګل وغږيږى، بيا به صِرف د قبيلو مشران ستا نه راغونډيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3673, 'Numbers 10:5', 'Numbers', 10, 5, '&nbsp;کله چې بيګل په لنډ آواز وغږيږى، نو د نمرخاتۀ په طرف قبيلې به خېمې وړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3674, 'Numbers 10:6', 'Numbers', 10, 6, '&nbsp;کله چې په دوېم ځل بيګل وغږيږى، نو د جنوب طرف ته قبيلې به خېمې يوسى. چې بيګل په لنډ آواز غږيږى نو خېمې به وړلے شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3675, 'Numbers 10:7', 'Numbers', 10, 7, '&nbsp;د قوم د راغونډولو د خبر دپاره به بيګلې غږولے شى. خو دا آواز به لنډ نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3676, 'Numbers 10:8', 'Numbers', 10, 8, '&nbsp;د هارون اِمامان زامن به بيګل غږوى. دا قانون به په راتلونکى ټولو وختونو کښې منلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3677, 'Numbers 10:9', 'Numbers', 10, 9, '&nbsp;کله چې ستاسو په مُلک کښې جنګ وى او دشمن په تاسو باندې حمله کوى، نو په لنډ آواز به د خطرې بيګل وغږوئ. زۀ، مالِک خُدائ ستاسو خُدائ پاک، به ستاسو مدد وکړم او ستاسو د دشمنانو نه به مو بچ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3678, 'Numbers 10:10', 'Numbers', 10, 10, '&nbsp;د خوشحالۍ په ورځو کښې، د مياشتې په ليدو او ستاسو په نورو مقررو اخترونو کښې، کله چې تاسو سوزېدونکې نذرانې او خپلې د سلامتۍ نذرانې پېش کوئ نو تاسو به دې باندې بيګلې غږوئ. د بيګل آواز به ما ته ستاسو سره لوظ راپه ياد کړى چې زۀ مالِک خُدائ ستاسو خُدائ پاک يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3679, 'Numbers 10:11', 'Numbers', 10, 11, '&nbsp;د دوېم کال د دوېمې مياشتې په شلمه ورځ د هغې نه پس چې اِسرائيليان د مِصر مُلک نه راوتلى وُو، د مالِک خُدائ د حضور د خېمې نه وريځ اوچته شوه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3680, 'Numbers 10:12', 'Numbers', 10, 12, '&nbsp;او اِسرائيليان د سينا د بيابان نه په سفر روان شول. وريځ د فاران په صحرا کښې ايساره شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3681, 'Numbers 10:13', 'Numbers', 10, 13, '&nbsp;هغوئ د موسىٰ په ذريعه د مالِک خُدائ د حُکم په مطابق سفر شروع کړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3682, 'Numbers 10:14', 'Numbers', 10, 14, '&nbsp;او هر ځل چې هغوئ تلل، نو هغوئ به هم په هغه ترتيب باندې وُو. څوک چې د يهوداه قبيلې د لښکر د جنډې لاندې وُو هغوئ قبيله په قبيله اول روان شول، د هغوئ مشر نحشون زوئ د عمى‌نداب وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3683, 'Numbers 10:15', 'Numbers', 10, 15, '&nbsp;نتنى‌ايل زوئ د ضُعر د يساکار قبيلې مشر وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3684, 'Numbers 10:16', 'Numbers', 10, 16, '&nbsp;او اِلياب زوئ د حيلون د زبولون قبيلې مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3685, 'Numbers 10:17', 'Numbers', 10, 17, '&nbsp;بيا به خېمه راکوزه کړے شوه او د جيرسون او مرارى قبيلې به روانې شوې، چې هغوئ به خېمه وړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3686, 'Numbers 10:18', 'Numbers', 10, 18, '&nbsp;بيا، څوک چې د روبين قبيلې د لښکر د جنډې لاندې وُو، هغوئ به قبيله په قبيله روان شول، د هغوئ مشر اليصور زوئ د شدِيُور وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3687, 'Numbers 10:19', 'Numbers', 10, 19, '&nbsp;د شمعون قبيلې مشر سلومى‌اېل زوئ د صورى‌شدى وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3688, 'Numbers 10:20', 'Numbers', 10, 20, '&nbsp;اِلياسف زوئ د دعو‌اېل د جاد قبيلې مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3689, 'Numbers 10:21', 'Numbers', 10, 21, '&nbsp;بيا به قُهاتيان روان شول، هغوئ به مقدس سامان وړلو. چې هغوئ به کوم وخت د خېمو بل ځائ ته ورسېدل، نو خېمه به بيا ودرولے شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3690, 'Numbers 10:22', 'Numbers', 10, 22, '&nbsp;بيا، څوک چې د اِفرائيم قبيلې د لښکر د جنډې لاندې وُو، هغوئ به قبيله په قبيله روان شول، د هغوئ مشر اليسمع زوئ د عميهود وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3691, 'Numbers 10:23', 'Numbers', 10, 23, '&nbsp;د منسى قبيلې مشر ګملى‌اېل زوئ د فداهصور وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3692, 'Numbers 10:24', 'Numbers', 10, 24, '&nbsp;او د بنيامين قبيلې مشر ابِدان زوئ د جدعونى وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3693, 'Numbers 10:25', 'Numbers', 10, 25, '&nbsp;په آخر کښې، څوک چې د دان قبيلې د لښکر د جنډې لاندې وُو، چا چې د ټولو لښکرو د وروستو نه حِفاظت کولو، هغوئ قبيله په قبيله روان شول، د هغوئ مشر د عمى‌شدى زوئ اخيعزر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3694, 'Numbers 10:26', 'Numbers', 10, 26, '&nbsp;د آشر قبيلې مشر فجعى‌اېل زوئ د عکران وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3695, 'Numbers 10:27', 'Numbers', 10, 27, '&nbsp;او د نفتالى قبيلې مشر اخيرع زوئ د عينان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3696, 'Numbers 10:28', 'Numbers', 10, 28, '&nbsp;نو داسې، اِسرائيليان قبيله په قبيله، په دې ترتيب روان وُو، چې کله به هم هغوئ خېمې وړلې او سفر يې کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3697, 'Numbers 10:29', 'Numbers', 10, 29, '&nbsp;موسىٰ خپل اوښى حوباب ته وفرمائيل چې د يترو ميديانى زوئ وو، ”مونږ هغه ځائ ته په سفر روانېږُو چې مالِک خُدائ فرمائيلى دى چې هغه به يې مونږ له راکړى. هغۀ وعده کړې ده چې هغه به اِسرائيليان مالدار کړى، نو مونږ سره لاړ شه او مونږ به تا سره ښېګړه وکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3698, 'Numbers 10:30', 'Numbers', 10, 30, '&nbsp;حوباب ووئيل، ”نه، زۀ واپس خپل مُلک ته ځم چې د خپلو خلقو سره يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3699, 'Numbers 10:31', 'Numbers', 10, 31, '&nbsp;موسىٰ ورته وفرمائيل، ”زۀ تا ته مِنت کوم چې زمونږ نه مۀ ځه، تا ته پته ده چې مونږ به په صحرا کښې چرته خېمې ولګوو او تۀ به مونږ ته لار ښائې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(3700, 'Numbers 10:32', 'Numbers', 10, 32, '&nbsp;کۀ تۀ مونږ سره لاړ شې، نو چې مالِک خُدائ مونږ له څومره برکتونه هم راکوى نو په هغې کښې به ستا حِصه وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');